<script setup lang="ts">
import {ref,onMounted} from 'vue';import {companyOptions,api,errorText,date} from '../api';import PageHeading from '../components/PageHeading.vue';import Modal from '../components/Modal.vue';import {Plus,ShieldCheck} from 'lucide-vue-next';import {useAuth} from '../stores/auth';import {isDemo} from '../demo';
const roles:Record<string,string>={admin:'Administrador',accountant:'Contador',reviewer:'Revisor',client:'Cliente'};
const memberId=ref<number|null>(null);
function editMember(u:any){memberId.value=u.id;user.value={name:u.name,email:u.email,password:'',role:u.role,company_ids:[...u.company_ids]};show.value=true;}
function newMember(){memberId.value=null;user.value={name:'',email:'',password:'',role:'accountant',company_ids:[]};show.value=true;}
const auth=useAuth(),settings=ref<any>(null),templates=ref<any[]>([]),companies=ref<any[]>([]),activity=ref<any[]>([]),error=ref(''),message=ref(''),busy=ref(false),tab=ref('team'),show=ref(false),studyName=ref('');const user=ref({name:'',email:'',password:'',role:'accountant',company_ids:[] as number[]});const engagement=ref({company_id:'',work_template_id:'',monthly_fee:150000,starts_on:new Date().toISOString().slice(0,10)});async function load(){try{const [s,t,c,a]=await Promise.all([api.get('/settings'),api.get('/templates'),companyOptions(),api.get('/activity')]);settings.value=s.data;studyName.value=s.data.study.name;templates.value=t.data;companies.value=c;activity.value=a.data.data;}catch(e){error.value=errorText(e);}}async function create(){busy.value=true;try{if(memberId.value)await api.patch('/members/'+memberId.value,user.value);else await api.post('/members',user.value);show.value=false;user.value={name:'',email:'',password:'',role:'accountant',company_ids:[]};await load();}catch(e){error.value=errorText(e);}finally{busy.value=false;}}async function engage(){busy.value=true;message.value='';try{await api.post('/engagements',engagement.value);message.value=isDemo?'Servicio de ejemplo guardado en la ficha. La demo no ejecuta tareas programadas.':'Servicio recurrente guardado. Se generará con el comando programado del período.';}catch(e){error.value=errorText(e);}finally{busy.value=false;}}async function saveStudy(){busy.value=true;try{await api.put('/settings',{name:studyName.value});await auth.init();message.value='Nombre del estudio actualizado.';}catch(e){error.value=errorText(e);}finally{busy.value=false;}}onMounted(load);
</script>
<template><PageHeading title="Configuración" subtitle="Tu equipo, tus procesos y los accesos del estudio."/><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="message" class="success" role="status">{{message}}</p><div class="filter-tabs tabs-large"><button v-for="t in [{id:'team',name:'Equipo y accesos'},{id:'templates',name:'Servicios recurrentes'},{id:'integrations',name:'Estudio e integraciones'},{id:'audit',name:'Auditoría'}]" :key="t.id" @click="tab=t.id" :aria-pressed="tab===t.id">{{t.name}}</button></div><template v-if="settings"><section class="panel" v-if="tab==='team'"><div class="panel-heading"><h2>Personas y permisos</h2><button class="button primary" @click="newMember"><Plus :size="15"/>Crear acceso</button></div><div class="list-row" v-for="u in settings.members" :key="u.id"><div><strong>{{u.name}}</strong><small>{{u.email}} · {{u.company_ids.length}} empresas asignadas</small></div><div class="actions"><span class="badge">{{roles[u.role]}}</span><button class="button" @click="editMember(u)">Editar permisos</button></div></div><div class="panel-note"><ShieldCheck :size="15"/> Los administradores acceden a toda la cartera. Los demás roles solo a sus empresas asignadas.</div></section><section v-if="tab==='templates'" class="panel"><div class="panel-heading"><h2>Asignar servicio mensual</h2></div><form class="stack-form settings-form" @submit.prevent="engage"><label>Empresa<select v-model="engagement.company_id" required><option value="" disabled>Selecciona empresa</option><option v-for="c in companies" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>Plantilla<select v-model="engagement.work_template_id" required><option value="" disabled>Selecciona plantilla</option><option v-for="t in templates" :key="t.id" :value="t.id">{{t.name}}</option></select></label><label>Honorario mensual CLP<input type="number" v-model.number="engagement.monthly_fee" min="0" required></label><label>Inicio del servicio<input type="date" v-model="engagement.starts_on" required></label><button class="button primary" :disabled="busy">Guardar servicio recurrente</button></form><div class="list-row" v-for="t in templates" :key="t.id"><div><strong>{{t.name}}</strong><small>{{t.checklist.length}} pasos · {{t.requests.length}} antecedentes</small></div><span class="badge accepted">Plantilla activa</span></div></section><section v-if="tab==='integrations'" class="panel"><div class="panel-heading"><h2>Identidad del estudio</h2></div><form class="stack-form settings-form" @submit.prevent="saveStudy"><label>Nombre del estudio<input v-model="studyName" required maxlength="180"></label><button class="button primary" :disabled="busy">Guardar nombre</button></form><div class="list-row"><div><strong>Correo electrónico</strong><small>{{settings.integrations.email==='log'?'Modo registro: no envía correos externos.':'Transporte configurado. Verifica la entrega en tu servidor.'}}</small></div><span class="badge">{{settings.integrations.email==='log'?'Sin envío':'Configurado'}}</span></div><div class="list-row" v-for="name in ['WhatsApp Cloud API','Pasarela de pagos','SII y portales públicos','Inteligencia artificial']" :key="name"><strong>{{name}}</strong><span class="badge pending">No configurado</span></div></section><section v-if="tab==='audit'" class="panel"><div class="panel-heading"><h2>Últimos movimientos</h2></div><div v-for="a in activity" :key="a.id" class="list-row"><div><strong>{{a.action}}</strong><small>{{a.entity_type}} #{{a.entity_id}} · Usuario #{{a.user_id}} · {{date(a.created_at)}}</small></div></div><p v-if="!activity.length" class="empty">Aún no hay movimientos registrados.</p></section></template><Modal v-if="show" :title="memberId?'Editar permisos':'Crear acceso'" @close="show=false"><form class="stack-form" @submit.prevent="create"><label v-if="!memberId">Nombre<input v-model="user.name" required maxlength="180"></label><label v-if="!memberId">Correo<input type="email" v-model="user.email" required></label><label v-if="!memberId">Contraseña inicial (mínimo 12 caracteres)<input type="password" v-model="user.password" minlength="12" autocomplete="new-password" required></label><label>Rol<select v-model="user.role"><option value="accountant">Contador</option><option value="reviewer">Revisor</option><option value="client">Cliente</option><option value="admin">Administrador</option></select></label><fieldset><legend>Empresas autorizadas</legend><label class="checkbox" v-for="c in companies" :key="c.id"><input type="checkbox" v-model="user.company_ids" :value="c.id">{{c.name}}</label></fieldset><p v-if="error" class="error">{{error}}</p><button class="button primary" :disabled="busy">{{memberId?'Guardar permisos':'Crear usuario'}}</button></form></Modal></template>
